  long texture_resolution;
  long ui_scale;
  long render_resolution;
  long window_mode;
  long frame_rate_limit;
  long texture_filtering;
  long brightness;
  long master_volume;
  long maximum_zoom_out;
  bool zoom_enabled;
  bool display_clouds;
  bool display_shadows;
  bool display_battlefield_ambients;
  bool trilinear_filter;
  bool full_screen;
  bool reverb_enabled;
  bool wait_for_vsync;
  bool ambient_sounds;
  bool show_blood;
  bool music_enabled;
  bool right_hand_mouse_orientation;
  bool unit_lighting;
