void ee_screens_hud_refresh(const EeScreensHudUnit *unit, EeScreensHudRefresh *out);

/// A slot of `source` (`EE_SCREENS_LE_SOURCE_*`) into `out`, its name into `name` (up to `capacity` bytes); the
